@Component("gateway-handler")
@ProcessingGroup("gateway-processing-group")
public class GatewayEventHandler {
	
	// core constructor
	GatewayEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateGatewayEvent
     */
    @EventHandler
    public void handle( CreateGatewayEvent event) {
        entityManager.persist(new Gateway(event.getGatewayId(), event.getSoftwareVersion(), event.getSite(), event.getRoom(), event.getDevices(), event.getEdgeApplications(), event.getCertificates(), event.getDigitalTwin(), event.getNetworkProfiles(), event.getStatus()));
    }

    /*
     * @param	event UpdateGatewayEvent
     */
    @EventHandler
    public Gateway handle( UpdateGatewayEvent event) {
    	entityManager.merge(new Gateway(event.getGatewayId(), event.getSoftwareVersion(), event.getSite(), event.getRoom(), event.getDevices(), event.getEdgeApplications(), event.getCertificates(), event.getDigitalTwin(), event.getNetworkProfiles(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteGatewayEvent
     */
    @EventHandler
    public void on( DeleteGatewayEvent event) {
    	Gateway entity = new Gateway();
   
    	// ------------------------------------------
    	// apply the GatewayId
    	// ------------------------------------------
    	entity.setGatewayId( event.getGatewayId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final GatewayRepository gatewayEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(GatewayEventHandler.class.getName());

}
